    if m == 'softplus':
        return np.logaddexp(-k * u, k * u)
    if m == 'sin':
        return np.sin(k * u)
    if m == 'gauss':
        return np.exp(-(k * u) ** 2)
    if m == 'rational':
        return 1 / (1 + (k * u) ** 2)
    if m == 'odd_rational':
        return u / (1 + (k * u) ** 2)
    if m == 'atan':
        return np.arctan(k * u)

def poly(X, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(X))] + [np.prod(X[:, j], axis=1) for i in range(1, d + 1) for j in combinations_with_replacement(range(X.shape[1]), i)])

def panel(u, v, m, idx):
    from scipy.optimize import minimize_scalar

    def design(k, X):
        return aff(np.c_[X, link(X, k, m)])

    def f(k):
        d = design(k, u[idx])
        return np.mean((d @ fit(d, v[idx]) - v[idx]) ** 2)
    r = minimize_scalar(f, bounds=(0.1, 4.5), method='bounded')
    k = r.x
    w = fit(design(k, u[idx]), v[idx])
    return (k, w, lambda X: design(k, X) @ w)
